import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Custom filter - only allows alphanumeric and some punctuation
    // NOTE: This is intentionally bypassable via unicode normalization
    private String lightSanitize(String input) {
        if (input == null) return null;
        // Remove obvious attack chars but allow unicode letters
        return input.replaceAll("[;\\\\]", "");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Apply light sanitization
        reportType = lightSanitize(reportType);
        department = lightSanitize(department);
        sortCol = lightSanitize(sortCol);

        String query = buildQuery(reportType, dateRange, department, sortCol);

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            out.print("[\n");
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            boolean first = true;

            while (rs.next()) {
                if (!first) out.print(",\n");
                out.print("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(", ");
                    out.print("\"" + meta.getColumnName(i) + "\": ");
                    out.print("\"" + rs.getString(i) + "\"");
                }
                out.print("}");
                first = false;
            }
            out.print("\n]");

        } catch (SQLException e) {
            resp.sendError(500, "Query failed: " + e.getMessage());
        }
    }

    private String buildQuery(String type, String range, String dept, String sort) {
        StringBuilder sb = new StringBuilder();

        switch (type) {
            case "sales":
                sb.append("SELECT id, amount, region, sale_date FROM sales");
                break;
            case "inventory":
                sb.append("SELECT sku, quantity, warehouse, last_updated FROM inventory");
                break;
            default:
                sb.append("SELECT * FROM reports WHERE type = '" + type + "'");
        }

        if (dept != null && !dept.isEmpty()) {
            sb.append(" AND department = '" + dept + "'");
        }

        // Date range filter
        if (range.equals("week")) {
            sb.append(" AND created_at > NOW() - INTERVAL '7 days'");
        } else if (range.equals("month")) {
            sb.append(" AND created_at > NOW() - INTERVAL '30 days'");
        }

        // Sort column - directly interpolated
        if (sort != null && !sort.isEmpty()) {
            sb.append(" ORDER BY " + sort);
        }

        return sb.toString();
    }
}
